// A libFuzzer entry point for complete files.

import RasterWebPCore
import RasterWebPDecoder

/// Decodes one input generated by libFuzzer, and every frame of it if it is an animation.
@_cdecl("LLVMFuzzerTestOneInput")
public func fuzzDecoder(_ data: UnsafePointer<UInt8>?, _ count: Int) -> CInt {
    let bytes = UnsafeBufferPointer(start: data, count: count)

    var options = WebPDecodingOptions()
    options.limits.maximumPixelCount = 1 << 20
    options.limits.maximumMemoryByteCount = 1 << 26
    // The frames of an animation together get the budget of one still image.
    options.limits.maximumAnimationPixelCount = 1 << 20

    if let image = try? WebPDecoder.decode(bytes.span, options: options) {
        precondition(image.pixels.count == image.width * image.height * 4)
    }

    // A still image would only decode again, so only animations take the frame-by-frame path.
    guard let info = try? WebPImageInfo(parsing: bytes.span), info.isAnimated,
        var decoder = try? WebPAnimationDecoder(Array(bytes), options: options)
    else {
        return 0
    }
    let frameCount = decoder.frames.count
    var index = 0
    while let frame = try? decoder.nextFrame() {
        precondition(frame.index == index && index < frameCount)
        precondition(frame.image.width == decoder.info.width && frame.image.height == decoder.info.height)
        index += 1
    }
    return 0
}
